import { autoAssetsConfig } from "../../autoAssetsConfig";
import { preloadAssets } from "../../common/game-core";
import { preloadHtmlImages } from "../../common/html";
import { addHtmlLoaderToPhaser } from "../../common/load";
import type { IPreloadAllAssetsBackgroundStage } from "./types";

interface IPreloadAllAssetsProps {
  scene: Phaser.Scene;
  backgroundStages: IPreloadAllAssetsBackgroundStage[];
}

const htmlProgressBarConfig = {
  loaderElementId: "loader",
  cssVarProgressName: "--progress",
} as const;

/** Загружает Phaser assets и заранее прогревает HTML-фоны без участия в loader progress. */
export function preloadAllAssets(props: IPreloadAllAssetsProps): void {
  /** подгрузка автоконфига автоматически подгружает все в assets **/
  initHtmlProgressBar(props.scene);
  preloadAssets(props.scene, autoAssetsConfig.preload);
  preloadHtmlImages({
    urls: getBackgroundUrls(props.backgroundStages),
  }).catch((error: unknown) => {
    console.warn("preloadHtmlImages failed", error);
  });
}

/** Подключает HTML progress bar к событиям Phaser loader. */
function initHtmlProgressBar(scene: Phaser.Scene): void {
  addHtmlLoaderToPhaser({
    scene,
    loaderVarHosId: htmlProgressBarConfig.loaderElementId,
    cssVarProgressName: htmlProgressBarConfig.cssVarProgressName,
  });
}

/** Собирает все URL фоновых слоев из декларативного конфига. */
function getBackgroundUrls(backgroundStages: IPreloadAllAssetsBackgroundStage[]): string[] {
  const urls: string[] = [];

  for (const stage of backgroundStages) {
    urls.push(stage.url);

    if (stage.fallbackUrl) {
      urls.push(stage.fallbackUrl);
    }

    if (stage.defaultUrl) {
      urls.push(stage.defaultUrl);
    }
  }

  return urls;
}
