import { makeContainerInteractive } from "../../../../common";
import { cinderella2048ViewConfig } from "../constants";

interface ICinderella2048DialogButtonProps {
  scene: Phaser.Scene;
  text: string;
  width: number;
  height: number;
  variant?: "primary" | "secondary";
  onClick: () => void;
}

/** Рисует кнопку модального диалога Cinderella 2048. */
export class Cinderella2048DialogButton extends Phaser.GameObjects.Container {
  private background: Phaser.GameObjects.Graphics;
  private label: Phaser.GameObjects.Text;
  private props: ICinderella2048DialogButtonProps;

  /** Создает кнопку диалога с локальной интерактивностью. */
  constructor(props: ICinderella2048DialogButtonProps) {
    super(props.scene, 0, 0);

    this.props = props;
    this.background = new Phaser.GameObjects.Graphics(props.scene);
    this.label = new Phaser.GameObjects.Text(props.scene, 0, 0, props.text, {
      fontFamily: cinderella2048ViewConfig.fontFamily,
      fontSize: "19px",
      fontStyle: "800",
      color: props.variant === "secondary"
        ? cinderella2048ViewConfig.colors.secondaryButtonText
        : cinderella2048ViewConfig.colors.buttonText,
    });

    this.label.setOrigin(0.5);
    this.add([this.background, this.label]);
    this.draw(false);
    makeContainerInteractive(this);

    this.on(Phaser.Input.Events.POINTER_DOWN, this.handlePointerDown, this);
    this.on(Phaser.Input.Events.POINTER_UP, this.handlePointerUp, this);
    this.on(Phaser.Input.Events.POINTER_OVER, this.handlePointerOver, this);
    this.on(Phaser.Input.Events.POINTER_OUT, this.handlePointerOut, this);
  }

  /** Уничтожает кнопку и снимает подписки ввода. */
  destroy(fromScene?: boolean): void {
    this.off(Phaser.Input.Events.POINTER_DOWN, this.handlePointerDown, this);
    this.off(Phaser.Input.Events.POINTER_UP, this.handlePointerUp, this);
    this.off(Phaser.Input.Events.POINTER_OVER, this.handlePointerOver, this);
    this.off(Phaser.Input.Events.POINTER_OUT, this.handlePointerOut, this);
    super.destroy(fromScene);
  }

  /** Перерисовывает фон с учетом hover-состояния. */
  private draw(isHover: boolean): void {
    const { width, height, variant } = this.props;
    const radius = height / 2;

    this.background.clear();

    if (variant === "secondary") {
      this.background.fillStyle(0xffffff, isHover ? 0.24 : 0.16);
      this.background.fillRoundedRect(-width / 2, -height / 2, width, height, radius);
      this.background.lineStyle(1, 0xffffff, 0.2);
      this.background.strokeRoundedRect(-width / 2, -height / 2, width, height, radius);
      return;
    }

    this.background.fillGradientStyle(0xfff0a3, 0xfff0a3, 0xf5c95d, 0xf5c95d, 1);
    this.background.fillRoundedRect(-width / 2, -height / 2, width, height, radius);
  }

  /** Обрабатывает нажатие кнопки. */
  private handlePointerDown(): void {
    this.setScale(0.98);
  }

  /** Обрабатывает отпускание кнопки. */
  private handlePointerUp(): void {
    this.setScale(1);
    this.props.onClick();
  }

  /** Включает hover-состояние кнопки. */
  private handlePointerOver(): void {
    this.draw(true);
    this.setScale(1.02);
  }

  /** Выключает hover-состояние кнопки. */
  private handlePointerOut(): void {
    this.draw(false);
    this.setScale(1);
  }
}
