/** Возвращает степени двойки в заданном включительном диапазоне. */
export function getPowersOfTwo(min: number, max: number): number[] {
  const powers: number[] = [];

  if (!Number.isFinite(min) || !Number.isFinite(max) || max < 1 || min > max) {
    return powers;
  }

  let value = 1;

  while (value < min) {
    value *= 2;
  }

  while (value <= max) {
    powers.push(value);
    value *= 2;
  }

  return powers;
}
