import { createGeneratedParticleEffectSet, IGeneratedParticleEffectFrameConfig } from "../generatedParticleEffectSet";
import { IParticleEffectSetConfig } from "../types";

export const basicGeneratedParticleFrameNames = {
    circle: "particle_circle",
    diamond: "particle_diamond",
    star: "particle_star",
} as const;

const basicGeneratedParticleEffectSetConfig = {
    textureName: "basic-runtime-particles",
    frameSize: 64,
    shapeSize: 48,
} as const;

interface ICreateBasicGeneratedParticleEffectSetProps {
    scene: Phaser.Scene;
    textureName?: string;
    frameSize?: number;
    shapeSize?: number;
}

/** Создает базовый набор runtime-частиц circle/diamond/star для ParticleEffectLayer. */
export function createBasicGeneratedParticleEffectSet(
    props: ICreateBasicGeneratedParticleEffectSetProps,
): IParticleEffectSetConfig {
    const frameSize = props.frameSize ?? basicGeneratedParticleEffectSetConfig.frameSize;
    const shapeSize = props.shapeSize ?? basicGeneratedParticleEffectSetConfig.shapeSize;

    return createGeneratedParticleEffectSet({
        scene: props.scene,
        textureName: props.textureName ?? basicGeneratedParticleEffectSetConfig.textureName,
        frameWidth: frameSize,
        frameHeight: frameSize,
        frames: createBasicGeneratedParticleFrameConfigs({shapeSize}),
    });
}

interface ICreateBasicGeneratedParticleFrameConfigsProps {
    shapeSize: number;
}

/** Возвращает генераторы базовых форм частиц без зависимости от конкретной сцены. */
function createBasicGeneratedParticleFrameConfigs(
    props: ICreateBasicGeneratedParticleFrameConfigsProps,
): IGeneratedParticleEffectFrameConfig[] {
    return [
        {
            frameName: basicGeneratedParticleFrameNames.circle,
            generatorFn: ({context, width, height}) => drawCircleFrame({
                context,
                width,
                height,
                shapeSize: props.shapeSize,
            }),
        },
        {
            frameName: basicGeneratedParticleFrameNames.diamond,
            generatorFn: ({context, width, height}) => drawDiamondFrame({
                context,
                width,
                height,
                shapeSize: props.shapeSize,
            }),
        },
        {
            frameName: basicGeneratedParticleFrameNames.star,
            generatorFn: ({context, width, height}) => drawStarFrame({
                context,
                width,
                height,
                shapeSize: props.shapeSize,
            }),
        },
    ];
}

interface IDrawBasicGeneratedParticleFrameProps {
    context: CanvasRenderingContext2D;
    width: number;
    height: number;
    shapeSize: number;
}

/** Рисует круг в центре frame-а. */
function drawCircleFrame(props: IDrawBasicGeneratedParticleFrameProps): void {
    const {context, width, height, shapeSize} = props;
    const radius = shapeSize / 2;

    context.fillStyle = "#ffffff";
    context.beginPath();
    context.arc(width / 2, height / 2, radius, 0, Math.PI * 2);
    context.closePath();
    context.fill();
}

/** Рисует ромб в центре frame-а. */
function drawDiamondFrame(props: IDrawBasicGeneratedParticleFrameProps): void {
    const {context, width, height, shapeSize} = props;
    const radius = shapeSize / 2;
    const centerX = width / 2;
    const centerY = height / 2;

    context.fillStyle = "#ffffff";
    context.beginPath();
    context.moveTo(centerX, centerY - radius);
    context.lineTo(centerX + radius, centerY);
    context.lineTo(centerX, centerY + radius);
    context.lineTo(centerX - radius, centerY);
    context.closePath();
    context.fill();
}

/** Рисует пятиконечную звезду с внутренним радиусом 45% от внешнего. */
function drawStarFrame(props: IDrawBasicGeneratedParticleFrameProps): void {
    const {context, width, height, shapeSize} = props;
    const points = 10;
    const radius = shapeSize / 2;
    const centerX = width / 2;
    const centerY = height / 2;

    context.fillStyle = "#ffffff";
    context.beginPath();

    for (let index = 0; index < points; index += 1) {
        const angle = -Math.PI / 2 + index * Math.PI / 5;
        const pointRadius = index % 2 === 0 ? radius : radius * 0.45;
        const x = centerX + Math.cos(angle) * pointRadius;
        const y = centerY + Math.sin(angle) * pointRadius;

        if (index === 0) {
            context.moveTo(x, y);
        } else {
            context.lineTo(x, y);
        }
    }

    context.closePath();
    context.fill();
}
