import type { ITileMergePolicy } from "./types";

interface ICreateTileMergePolicyProps {
  maxTileValue: number;
}

/**
 * Создает правило слияния для текущего сценария 2048.
 *
 * Алгоритм разрешает слияние только для одинаковых значений, если результат не превышает `maxTileValue`.
 * Это делает максимальную плитку финальной и защищает поле от плиток выше настроенного максимума.
 */
export function createTileMergePolicy(props: ICreateTileMergePolicyProps): ITileMergePolicy {
  const { maxTileValue } = props;

  return {
    canMerge: (leftValue, rightValue) => leftValue === rightValue && leftValue * 2 <= maxTileValue,
  };
}
