import { generateRuntimeTextures } from "../../../textures";
import { IParticleEffectSetConfig } from "../types";
import { IGeneratedParticleEffectFrameConfig } from "./types";

export interface ICreateGeneratedParticleEffectSetProps {
    scene: Phaser.Scene;
    textureName: string;
    frames: IGeneratedParticleEffectFrameConfig[];
    frameWidth?: number;
    frameHeight?: number;
}

const generatedParticleEffectSetConfig = {
    frameWidth: 64,
    frameHeight: 64,
} as const;

/** Создает runtime-текстуру с named frames и возвращает particleSet для ParticleEffectLayer. */
export function createGeneratedParticleEffectSet(
    props: ICreateGeneratedParticleEffectSetProps,
): IParticleEffectSetConfig {
    const {scene, textureName, frames} = props;
    const frameWidth = props.frameWidth ?? generatedParticleEffectSetConfig.frameWidth;
    const frameHeight = props.frameHeight ?? generatedParticleEffectSetConfig.frameHeight;

    if (frames.length === 0) {
        return {assets: []};
    }

    generateRuntimeTextures({
        scene,
        textures: [{
            textureName,
            width: frameWidth * frames.length,
            height: frameHeight,
            generatorFn: ({context}) => {
                drawGeneratedParticleFrames({
                    scene,
                    textureName,
                    frames,
                    frameWidth,
                    frameHeight,
                    context,
                });
            },
        }],
    });
    registerGeneratedParticleFrames({
        scene,
        textureName,
        frames,
        frameWidth,
        frameHeight,
    });

    return {
        assets: frames.map((frame) => ({
            url: textureName,
            frameName: frame.frameName,
        })),
    };
}

interface IDrawGeneratedParticleFramesProps {
    scene: Phaser.Scene;
    textureName: string;
    frames: IGeneratedParticleEffectFrameConfig[];
    frameWidth: number;
    frameHeight: number;
    context: CanvasRenderingContext2D;
}

/** Рисует каждый frame в локальных координатах своей ячейки runtime-текстуры. */
function drawGeneratedParticleFrames(props: IDrawGeneratedParticleFramesProps): void {
    const {scene, textureName, frames, frameWidth, frameHeight, context} = props;

    frames.forEach((frame, index) => {
        context.save();
        context.translate(index * frameWidth, 0);
        frame.generatorFn({
            scene,
            textureName,
            frameName: frame.frameName,
            width: frameWidth,
            height: frameHeight,
            context,
        });
        context.restore();
    });
}

interface IRegisterGeneratedParticleFramesProps {
    scene: Phaser.Scene;
    textureName: string;
    frames: IGeneratedParticleEffectFrameConfig[];
    frameWidth: number;
    frameHeight: number;
}

/** Регистрирует named frames поверх сгенерированной canvas-текстуры. */
function registerGeneratedParticleFrames(props: IRegisterGeneratedParticleFramesProps): void {
    const {scene, textureName, frames, frameWidth, frameHeight} = props;
    const texture = scene.textures.get(textureName);

    frames.forEach((frame, index) => {
        if (texture.has(frame.frameName)) {
            return;
        }

        texture.add(frame.frameName, 0, index * frameWidth, 0, frameWidth, frameHeight);
    });
}
