import { cinderella2048ViewConfig } from "../constants";
import { Cinderella2048DialogButton } from "./Cinderella2048DialogButton";

export interface ICinderella2048GameOverDialogCopy {
  /** Заголовок диалога, например "Ходов больше нет". */
  title: string;
  /** Основное сообщение с объяснением результата игры. */
  message: string;
  /** Текст основной кнопки, например "Новая игра". */
  primaryText: string;
  /** Текст вторичной кнопки, если текущий результат игры допускает второе действие. */
  secondaryText?: string;
}

interface ICinderella2048GameOverDialogViewProps {
  /** Modal scene, внутри которой рисуется карточка диалога. */
  scene: Phaser.Scene;
  /** Тексты для текущего состояния игры. */
  copy: ICinderella2048GameOverDialogCopy;
  /** Действие основной кнопки. */
  onPrimaryClick: () => void;
  /** Действие вторичной кнопки. */
  onSecondaryClick: () => void;
}

/** Настройки layout карточки, от которых зависят bounds для CommonModal. */
const cinderella2048DialogViewConfig = {
  width: 440,
  height: 250,
  radius: 22,
  titleY: -72,
  messageY: -12,
  buttonsY: 78,
  primaryButtonX: -82,
  secondaryButtonX: 88,
  messageWidth: 384,
} as const;

/** Рисует содержимое модального окна победы или конца игры. */
export class Cinderella2048GameOverDialogView extends Phaser.GameObjects.Container {
  private readonly dialogWidth = cinderella2048DialogViewConfig.width;
  private readonly dialogHeight = cinderella2048DialogViewConfig.height;

  /** Создает карточку диалога с текстом и двумя действиями. */
  constructor(props: ICinderella2048GameOverDialogViewProps) {
    super(props.scene, 0, 0);

    const card = new Phaser.GameObjects.Graphics(props.scene);
    const title = new Phaser.GameObjects.Text(
      props.scene,
      0,
      cinderella2048DialogViewConfig.titleY,
      props.copy.title,
      {
        fontFamily: cinderella2048ViewConfig.fontFamily,
        fontSize: "40px",
        fontStyle: "900",
        color: cinderella2048ViewConfig.colors.text,
        align: "center",
      },
    );
    const message = new Phaser.GameObjects.Text(
      props.scene,
      0,
      cinderella2048DialogViewConfig.messageY,
      props.copy.message,
      {
        fontFamily: cinderella2048ViewConfig.fontFamily,
        fontSize: "18px",
        color: "#f3e9ff",
        align: "center",
        wordWrap: { width: cinderella2048DialogViewConfig.messageWidth },
      },
    );
    const hasSecondaryButton = props.copy.secondaryText !== undefined;
    const primaryButton = new Cinderella2048DialogButton({
      scene: props.scene,
      text: props.copy.primaryText,
      width: 150,
      height: 46,
      onClick: props.onPrimaryClick,
    });

    this.drawCard(card);
    title.setOrigin(0.5);
    message.setOrigin(0.5);
    primaryButton.setPosition(
      hasSecondaryButton ? cinderella2048DialogViewConfig.primaryButtonX : 0,
      cinderella2048DialogViewConfig.buttonsY,
    );
    this.add([card, title, message, primaryButton]);

    if (props.copy.secondaryText) {
      const secondaryButton = new Cinderella2048DialogButton({
        scene: props.scene,
        text: props.copy.secondaryText,
        width: 146,
        height: 46,
        variant: "secondary",
        onClick: props.onSecondaryClick,
      });

      secondaryButton.setPosition(cinderella2048DialogViewConfig.secondaryButtonX, cinderella2048DialogViewConfig.buttonsY);
      this.add(secondaryButton);
    }
  }

  /** Возвращает стабильные границы для CommonModal/Align. */
  getBounds(): Phaser.Geom.Rectangle {
    return new Phaser.Geom.Rectangle(
      this.x - this.dialogWidth / 2,
      this.y - this.dialogHeight / 2,
      this.dialogWidth,
      this.dialogHeight,
    );
  }

  /** Рисует фон карточки в локальных координатах view. */
  private drawCard(card: Phaser.GameObjects.Graphics): void {
    const width = cinderella2048DialogViewConfig.width;
    const height = cinderella2048DialogViewConfig.height;
    const radius = cinderella2048DialogViewConfig.radius;

    card.fillStyle(0xffffff, 0.14);
    card.fillRoundedRect(-width / 2, -height / 2, width, height, radius);
    card.lineStyle(1, 0xffffff, 0.24);
    card.strokeRoundedRect(-width / 2, -height / 2, width, height, radius);
  }
}
