import { cinderella2048Config } from "./constants";
import type { Cinderella2048StageValue } from "./constants";
import type { IGame2048Config, ITileSpawnPolicy, TileSpawnReason } from "./types";

interface ICreateTileSpawnPolicyProps {
  game2048Config: IGame2048Config;
}

interface IGetNextStageValueProps {
  stageValue: Cinderella2048StageValue;
  maxTileValue: number;
}

/** Создает политику спавна плиток для выбранного сценария партии. */
export function createTileSpawnPolicy(props: ICreateTileSpawnPolicyProps): ITileSpawnPolicy {
  const { game2048Config } = props;
  const stageValue = resolveStartStageValue(game2048Config.startStageValue);
  const nextStageValue = getNextStageValue({
    stageValue,
    maxTileValue: game2048Config.maxTileValue,
  });

  return {
    getTileValue: (reason) => getTileValueByReason({
      reason,
      stageValue,
      nextStageValue,
    }),
  };
}

/** Возвращает поддерживаемый стартовый этап или самый первый этап при ошибке в конфиге. */
function resolveStartStageValue(value: number): Cinderella2048StageValue {
  const stageValue = cinderella2048Config.supportedValues.find((supportedValue) => supportedValue === value);

  if (stageValue) {
    return stageValue;
  }

  return cinderella2048Config.supportedValues[0] as Cinderella2048StageValue;
}

/** Возвращает следующий этап, если он поддержан ассетами и не выходит за максимум сценария. */
function getNextStageValue(props: IGetNextStageValueProps): Cinderella2048StageValue | undefined {
  const stageIndex = cinderella2048Config.supportedValues.indexOf(props.stageValue);
  const nextStageValue = cinderella2048Config.supportedValues[stageIndex + 1] as Cinderella2048StageValue | undefined;

  if (!nextStageValue || nextStageValue > props.maxTileValue) {
    return undefined;
  }

  return nextStageValue;
}

/** Выбирает значение плитки: на старте N или N+1, после хода только N. */
function getTileValueByReason(props: {
  reason: TileSpawnReason;
  stageValue: Cinderella2048StageValue;
  nextStageValue?: Cinderella2048StageValue;
}): number {
  if (props.reason === "move" || !props.nextStageValue) {
    return props.stageValue;
  }

  return Math.random() < cinderella2048Config.initialBaseTileChance
    ? props.stageValue
    : props.nextStageValue;
}
