import { cheatCode } from "./cheats";
import { backgroundConfig } from "./config.backgrounds";
import { boardConfig } from "./config.board";
import { game2048Config } from "./config.game2048";
import { soundConfig } from "./config.sound";

/**
 * Возвращает конфиги игры с примененными dev-переопределениями.
 * ИСКЛЮЧЕНИЕ - бустрап конфиг Phaser пусть читается напрямую
 * */
export function getConfig() {
  const startLevel2048 = cheatCode.getStartLevel2048();

  return {
    backgroundConfig,
    boardConfig,
    game2048Config: {
      ...game2048Config,
      startStageValue: startLevel2048 ?? game2048Config.startStageValue,
    },
    soundConfig,
  };
}
