import { makeAlign } from "@kvisaz/phaser-sugar";
import { center, grid } from "../../../../../common";
import {
  cinderella2048Config,
  Cinderella2048GridModel,
  Cinderella2048TileModel,
} from "../model";
import type { ICinderella2048MergeAnimation } from "../model";
import type { ICind2048SpriteConfig } from "../types";
import { cinderella2048ViewConfig } from "../../constants";
import { Cinderella2048TileView } from "./Cinderella2048TileView";
import type {
  ICinderella2048BoardViewConfig,
  ICinderella2048CellBoundsProvider,
  ICinderella2048TileViewState,
  ITargetMergeViewState,
} from "./types";

interface ICinderella2048BoardViewProps {
  scene: Phaser.Scene;
  spriteConfig: ICind2048SpriteConfig;
  boardConfig: ICinderella2048BoardViewConfig;
}

interface IUpdateCinderella2048TileViewProps {
  tileView: Cinderella2048TileView;
  grid: Cinderella2048GridModel;
  time: number;
}

interface IDestroyInactiveCinderella2048TileViewProps {
  tileView: Cinderella2048TileView;
  tileId: number;
  time: number;
}

interface IDelayCinderella2048TileRevealProps {
  tileId: number;
  revealAt: number;
}

/** Отвечает за поле, пустые клетки и визуальные плитки. */
export class Cinderella2048BoardView extends Phaser.GameObjects.Container implements ICinderella2048CellBoundsProvider {
  private boardBackground: Phaser.GameObjects.NineSlice;
  private freeTileViews: Phaser.GameObjects.Image[][];
  private tilesLayer: Phaser.GameObjects.Container;
  private tileViews: Map<number, Cinderella2048TileView>;
  private mergeSlideAnimationsBySourceId: Map<number, ICinderella2048MergeAnimation>;
  private mergeTargetStatesByTargetId: Map<number, ITargetMergeViewState>;
  private delayedTileRevealUntilById: Map<number, number>;

  /** Создает доску 2048 и слой плиток. */
  constructor(private props: ICinderella2048BoardViewProps) {
    super(props.scene, 0, 0);

    this.boardBackground = this.createBoardBackground();
    this.freeTileViews = this.createFreeTileViews();
    this.tilesLayer = props.scene.add.container(0, 0);
    this.tileViews = new Map();
    this.mergeSlideAnimationsBySourceId = new Map();
    this.mergeTargetStatesByTargetId = new Map();
    this.delayedTileRevealUntilById = new Map();
    this.add([this.boardBackground, ...this.getFreeTileList(), this.tilesLayer]);
    this.setDepth(cinderella2048ViewConfig.depth.board);
    props.scene.add.existing(this);
    this.setupStaticBoardView();
    this.alignToSceneScreen();
  }

  /** Уничтожает доску и все связанные плитки. */
  destroy(fromScene?: boolean): void {
    this.clearMergeAnimations();
    this.clearTileRevealDelays();
    this.tileViews.forEach((tileView) => tileView.destroy());
    this.tileViews.clear();
    super.destroy(fromScene);
  }

  /** Возвращает актуальные bounds указанной клетки. */
  getCellBounds(row: number, col: number): Phaser.Geom.Rectangle {
    const bounds = this.freeTileViews[row][col].getBounds();

    return new Phaser.Geom.Rectangle(bounds.x - this.x, bounds.y - this.y, bounds.width, bounds.height);
  }

  /** Возвращает центр указанной клетки поля. */
  getCellCenter(row: number, col: number): { x: number; y: number } {
    const bounds = this.freeTileViews[row][col].getBounds();

    return {
      x: bounds.centerX,
      y: bounds.centerY,
    };
  }

  /** Возвращает центр всей доски. */
  getBoardCenter(): { x: number; y: number } {
    const bounds = this.boardBackground.getBounds();

    return {
      x: bounds.centerX,
      y: bounds.centerY,
    };
  }

  /** Проверяет, попадает ли точка в границы доски. */
  containsPoint(x: number, y: number): boolean {
    return this.boardBackground.getBounds().contains(x, y);
  }

  /** Откладывает первое появление новой плитки до завершения slide-фазы хода. */
  delayTileReveal(props: IDelayCinderella2048TileRevealProps): void {
    this.delayedTileRevealUntilById.set(props.tileId, props.revealAt);
  }

  /** Запоминает слияния хода, чтобы сначала проиграть скольжение исходных плиток. */
  playMergeAnimations(mergeAnimations: ICinderella2048MergeAnimation[]): void {
    this.clearMergeSlideAnimations();

    for (const mergeAnimation of mergeAnimations) {
      this.mergeSlideAnimationsBySourceId.set(mergeAnimation.sourceTileId, mergeAnimation);
      this.mergeTargetStatesByTargetId.set(mergeAnimation.targetTileId, this.createTargetMergeState(mergeAnimation));
    }
  }

  /** Сбрасывает все временные состояния отложенных слияний. */
  clearMergeAnimations(): void {
    this.clearMergeSlideAnimations();
    this.mergeTargetStatesByTargetId.clear();
  }

  /** Сбрасывает отложенное появление новых плиток. */
  clearTileRevealDelays(): void {
    this.delayedTileRevealUntilById.clear();
  }

  /** Обновляет только игровые плитки поверх уже созданной доски. */
  update(grid: Cinderella2048GridModel, time: number): void {
    this.syncTileViews(grid, time);

    this.tileViews.forEach((tileView) => {
      this.updateTileView({ tileView, grid, time });
    });
    this.cleanupFinishedMergeAnimations(time);
    this.cleanupFinishedTileRevealDelays(time);
  }

  /** Создает фон доски на базе atlas-frame с nine-slice отступами. */
  private createBoardBackground(): Phaser.GameObjects.NineSlice {
    const { scene } = this.props;
    const { background } = this.props.boardConfig.assets;
    const { boardOpacity } = this.props.boardConfig.layout;
    const backgroundView = scene.add.nineslice(
      0,
      0,
      background.textureName,
      background.frameName,
      1,
      1,
      background.nineSlicePadding,
      background.nineSlicePadding,
      background.nineSlicePadding,
      background.nineSlicePadding,
    );

    backgroundView.setOrigin(0, 0);
    backgroundView.setAlpha(boardOpacity);

    return backgroundView;
  }

  /** Создает изображения свободных клеток в порядке обхода сетки. */
  private createFreeTileViews(): Phaser.GameObjects.Image[][] {
    const { scene } = this.props;
    const { freeTile } = this.props.boardConfig.assets;
    const { freeTileOpacity, tileHeight, tileWidth } = this.props.boardConfig.layout;
    const freeTileViews: Phaser.GameObjects.Image[][] = [];

    for (let row = 0; row < cinderella2048Config.gridSize; row += 1) {
      const freeTileRow: Phaser.GameObjects.Image[] = [];

      for (let col = 0; col < cinderella2048Config.gridSize; col += 1) {
        const freeTileView = scene.add.image(0, 0, freeTile.textureName, freeTile.frameName);

        freeTileView.setOrigin(0.5);
        freeTileView.setDisplaySize(tileWidth, tileHeight);
        freeTileView.setAlpha(freeTileOpacity);
        freeTileRow.push(freeTileView);
      }

      freeTileViews.push(freeTileRow);
    }

    return freeTileViews;
  }

  /** Один раз выставляет сетку свободных клеток и центрирует фон вокруг нее. */
  private setupStaticBoardView(): void {
    const { boardPadding, tileGap } = this.props.boardConfig.layout;
    const firstTileBounds = this.freeTileViews[0][0].getBounds();
    const freeTileGrid = grid(this.freeTileViews, {
      cellWidth: firstTileBounds.width + tileGap,
      cellHeight: firstTileBounds.height + tileGap,
    });
    const gridBounds = freeTileGrid.getBounds();

    this.boardBackground.setSize(
      gridBounds.width + boardPadding * 2,
      gridBounds.height + boardPadding * 2,
    );
    center(this.boardBackground, freeTileGrid);
  }

  /** Центрирует доску по горизонтали и задает отступ от верхней границы экрана. */
  private alignToSceneScreen(): void {
    const { scene } = this.props;
    const { boardTop } = this.props.boardConfig.layout;

    makeAlign((align) => align.anchorSceneScreen(scene).centerX(this).topIn(this, boardTop));
  }

  /** Возвращает плоский список свободных клеток для добавления в контейнер. */
  private getFreeTileList(): Phaser.GameObjects.Image[] {
    return this.freeTileViews.flat();
  }

  /** Синхронизирует набор визуальных плиток с моделью поля. */
  private syncTileViews(grid: Cinderella2048GridModel, time: number): void {
    const activeIds = new Set<number>();

    grid.forEachTile((tile) => {
      activeIds.add(tile.id);

      if (this.isTileRevealDelayed(tile.id, time)) {
        return;
      }

      if (!this.tileViews.has(tile.id)) {
        const tileView = new Cinderella2048TileView({
          scene: this.scene,
          tile: this.createTileViewState(tile),
          cellBoundsProvider: this,
          spriteConfig: this.props.spriteConfig,
        });
        this.tilesLayer.add(tileView);
        this.tileViews.set(tile.id, tileView);
      }
    });

    this.tileViews.forEach((tileView, id) => {
      if (!activeIds.has(id)) {
        this.destroyInactiveTileView({ tileView, tileId: id, time });
      }
    });
  }

  /** Обновляет обычную или временную плитку слияния. */
  private updateTileView(props: IUpdateCinderella2048TileViewProps): void {
    const tile = this.findTileById(props.grid, props.tileView.tileId);

    if (tile) {
      const mergeTargetState = this.mergeTargetStatesByTargetId.get(tile.id);

      props.tileView.update({
        tile: this.createTileViewState(tile),
        cellBoundsProvider: this,
        time: props.time,
        displayValue: this.getDisplayValueForMerge(mergeTargetState, props.time),
        mergeStartedAt: mergeTargetState?.popStartedAt,
      });
      return;
    }

    const mergeAnimation = this.mergeSlideAnimationsBySourceId.get(props.tileView.tileId);

    if (mergeAnimation) {
      props.tileView.update({
        tile: this.createSourceMergeTileState(mergeAnimation),
        cellBoundsProvider: this,
        time: props.time,
      });
    }
  }

  /** Создает состояние обычной плитки с учетом отложенной spawn-анимации. */
  private createTileViewState(tile: Cinderella2048TileModel): ICinderella2048TileViewState {
    const revealAt = this.delayedTileRevealUntilById.get(tile.id);

    if (revealAt === undefined) {
      return tile;
    }

    return {
      id: tile.id,
      value: tile.value,
      row: tile.row,
      col: tile.col,
      fromRow: tile.fromRow,
      fromCol: tile.fromCol,
      createdAt: revealAt,
      moveStartedAt: tile.moveStartedAt,
      mergeStartedAt: tile.mergeStartedAt,
      justCreated: tile.justCreated,
      justMerged: tile.justMerged,
    };
  }

  /** Удаляет неактивную плитку, если она не нужна для slide-фазы слияния. */
  private destroyInactiveTileView(props: IDestroyInactiveCinderella2048TileViewProps): void {
    const mergeAnimation = this.mergeSlideAnimationsBySourceId.get(props.tileId);

    if (mergeAnimation && !this.isMergeSlideFinished(mergeAnimation, props.time)) {
      return;
    }

    props.tileView.destroy();
    this.tileViews.delete(props.tileId);
  }

  /** Проверяет, нужно ли пока скрывать новую плитку. */
  private isTileRevealDelayed(tileId: number, time: number): boolean {
    const revealAt = this.delayedTileRevealUntilById.get(tileId);

    return revealAt !== undefined && time < revealAt;
  }

  /** Создает временное состояние исходной плитки, которая летит в точку слияния. */
  private createSourceMergeTileState(mergeAnimation: ICinderella2048MergeAnimation): ICinderella2048TileViewState {
    return {
      id: mergeAnimation.sourceTileId,
      value: mergeAnimation.value,
      row: mergeAnimation.toRow,
      col: mergeAnimation.toCol,
      fromRow: mergeAnimation.fromRow,
      fromCol: mergeAnimation.fromCol,
      createdAt: mergeAnimation.startedAt,
      moveStartedAt: mergeAnimation.startedAt,
      mergeStartedAt: 0,
      justCreated: false,
      justMerged: false,
    };
  }

  /** Создает состояние целевой плитки с отдельным временем slide и pop-фазы. */
  private createTargetMergeState(mergeAnimation: ICinderella2048MergeAnimation): ITargetMergeViewState {
    const popStartedAt = mergeAnimation.startedAt + cinderella2048Config.timings.moveMs;

    return {
      displayValue: mergeAnimation.value,
      popStartedAt,
      clearAt: popStartedAt + cinderella2048Config.timings.mergeMs,
    };
  }

  /** Сбрасывает временные view исходных плиток без обрыва pop-анимаций target-плиток. */
  private clearMergeSlideAnimations(): void {
    this.mergeSlideAnimationsBySourceId.forEach((mergeAnimation) => {
      const tileView = this.tileViews.get(mergeAnimation.sourceTileId);

      if (tileView) {
        tileView.destroy();
        this.tileViews.delete(mergeAnimation.sourceTileId);
      }
    });

    this.mergeSlideAnimationsBySourceId.clear();
  }

  /** Возвращает старое значение целевой плитки, пока исходная еще скользит к ней. */
  private getDisplayValueForMerge(mergeTargetState: ITargetMergeViewState | undefined, time: number): number | undefined {
    if (!mergeTargetState || time >= mergeTargetState.popStartedAt) {
      return undefined;
    }

    return mergeTargetState.displayValue;
  }

  /** Проверяет, закончилась ли slide-фаза указанного слияния. */
  private isMergeSlideFinished(mergeAnimation: ICinderella2048MergeAnimation, time: number): boolean {
    return time >= mergeAnimation.startedAt + cinderella2048Config.timings.moveMs;
  }

  /** Удаляет slide-состояние source-плиток и pop-состояние target-плиток по их разным срокам жизни. */
  private cleanupFinishedMergeAnimations(time: number): void {
    const finishedSourceIds: number[] = [];
    const finishedTargetIds: number[] = [];

    this.mergeSlideAnimationsBySourceId.forEach((mergeAnimation, sourceTileId) => {
      if (this.isMergeSlideFinished(mergeAnimation, time)) {
        finishedSourceIds.push(sourceTileId);
      }
    });

    this.mergeTargetStatesByTargetId.forEach((mergeTargetState, targetTileId) => {
      if (time >= mergeTargetState.clearAt) {
        finishedTargetIds.push(targetTileId);
      }
    });

    for (const sourceTileId of finishedSourceIds) {
      const tileView = this.tileViews.get(sourceTileId);

      tileView?.destroy();
      this.tileViews.delete(sourceTileId);
      this.mergeSlideAnimationsBySourceId.delete(sourceTileId);
    }

    for (const targetTileId of finishedTargetIds) {
      this.mergeTargetStatesByTargetId.delete(targetTileId);
    }
  }

  /** Удаляет записи задержанного появления после окончания spawn-анимации. */
  private cleanupFinishedTileRevealDelays(time: number): void {
    const finishedTileIds: number[] = [];

    this.delayedTileRevealUntilById.forEach((revealAt, tileId) => {
      if (time >= revealAt + cinderella2048Config.timings.spawnMs) {
        finishedTileIds.push(tileId);
      }
    });

    for (const tileId of finishedTileIds) {
      this.delayedTileRevealUntilById.delete(tileId);
    }
  }

  /** Находит плитку по id в текущей модели поля. */
  private findTileById(grid: Cinderella2048GridModel, id: number): Cinderella2048TileModel | null {
    let result: Cinderella2048TileModel | null = null;

    grid.forEachTile((tile) => {
      if (tile.id === id) {
        result = tile;
      }
    });

    return result;
  }
}
