export enum MoveDirection {
  up='up',
  down='down',
  right='right',
  left='left'
}

export type TileSpawnReason = "initial" | "move";

export interface IGame2048Config {
  /** Этап, с которого начинается партия. */
  startStageValue: number;

  /** Максимальная плитка, доступная в текущем сценарии игры. */
  maxTileValue: number;

  /** Значение плитки, при котором показывается победный диалог. */
  winValue: number;
}

export interface ITileSpawnPolicy {
  /** Возвращает значение новой плитки для указанного типа спавна. */
  getTileValue(reason: TileSpawnReason): number;
}

export interface ITileMergePolicy {
  /** Проверяет, разрешено ли слияние одинаковых плиток с учетом лимитов текущего сценария. */
  canMerge(leftValue: number, rightValue: number): boolean;
}

export interface ICinderella2048Cell {
  row: number;
  col: number;
}

export interface ICinderella2048MergeEvent extends ICinderella2048Cell {
  value: number;
  sourceValue: number;
}

export interface ICinderella2048MergeAnimation {
  sourceTileId: number;
  targetTileId: number;
  fromRow: number;
  fromCol: number;
  toRow: number;
  toCol: number;
  value: number;
  nextValue: number;
  startedAt: number;
}

export interface ICinderella2048AnimationTransaction {
  merges: ICinderella2048MergeAnimation[];
}

export interface ICinderella2048MoveResult {
  moved: boolean;
  scoreGained: number;
  mergeEvents: ICinderella2048MergeEvent[];
  animation: ICinderella2048AnimationTransaction;
}

export interface ICinderella2048TileSnapshot {
  id: number;
  value: number;
  row: number;
  col: number;
  fromRow: number;
  fromCol: number;
  createdAt: number;
  moveStartedAt: number;
  mergeStartedAt: number;
  justCreated: boolean;
  justMerged: boolean;
  consumed: boolean;
}

export type Cinderella2048GridSnapshotRows = Array<Array<ICinderella2048TileSnapshot | null>>;

export interface ICinderella2048GridSnapshot {
  size: number;
  grid: Cinderella2048GridSnapshotRows;
  score: number;
  moves: number;
  won: boolean;
  over: boolean;
}
