import {
  basicGeneratedParticleFrameNames,
  createBasicGeneratedParticleEffectSet,
  SceneEvents,
} from "../../../../common";
import { cinderella2048ViewConfig } from "../constants";
import { Cinderella2048Particle } from "./Cinderella2048Particle";
import type { ICinderella2048EffectsEvents, ICinderella2048EffectsPayload } from "./events";
import type { ParticleShape } from "./types";
import { randomRange } from "./utils";

interface IAddCinderella2048ParticleProps {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  life: number;
  color: string;
  shape: ParticleShape;
}

const particleTextureConfig = {
  textureName: "tile-effect-runtime-particles",
  sourceShapeSize: 48,
  frameNameByShape: {
    circle: basicGeneratedParticleFrameNames.circle,
    diamond: basicGeneratedParticleFrameNames.diamond,
    star: basicGeneratedParticleFrameNames.star,
  },
};

/** Слушает события сцены и создает частицы для игровых эффектов. */
export class Cinderella2048EffectsLayer extends Phaser.GameObjects.Container {
  private particles: Cinderella2048Particle[];
  private sceneEvents: SceneEvents<ICinderella2048EffectsEvents>;

  /** Создает слой частиц и подписывает его на события сцены. */
  constructor(scene: Phaser.Scene) {
    super(scene, 0, 0);

    createBasicGeneratedParticleEffectSet({
      scene,
      textureName: particleTextureConfig.textureName,
      shapeSize: particleTextureConfig.sourceShapeSize,
    });

    this.particles = [];
    this.sceneEvents = new SceneEvents<ICinderella2048EffectsEvents>({ scene, autoUnSub: this });
    this.setDepth(cinderella2048ViewConfig.depth.particles);
    scene.add.existing(this);
    this.sceneEvents.on("cinderella2048MergeParticles", (payload) => this.spawnMerge(payload));
    this.sceneEvents.on("cinderella2048NewTileParticles", (payload) => this.spawnNewTile(payload));
    this.sceneEvents.on("cinderella2048VictoryParticles", (payload) => this.spawnRoyalBurst(payload));
    this.sceneEvents.on("cinderella2048ClearParticles", () => this.clearParticles());
  }

  /** Обновляет активные частицы и удаляет завершившиеся. */
  update(deltaMs: number): void {
    const deltaSeconds = deltaMs / 1000;
    const alive: Cinderella2048Particle[] = [];

    for (const particle of this.particles) {
      if (particle.updateParticle(deltaSeconds)) {
        alive.push(particle);
      } else {
        particle.destroy();
      }
    }

    this.particles = alive;
  }

  /** Очищает частицы и подписки слоя. */
  destroy(fromScene?: boolean): void {
    this.clearParticles();
    this.sceneEvents.unSubscribeAll();
    super.destroy(fromScene);
  }

  /** Создает вспышку при слиянии плиток. */
  private spawnMerge(payload: ICinderella2048EffectsPayload): void {
    for (let index = 0; index < 28; index += 1) {
      const angle = randomRange(0, Math.PI * 2);
      const speed = randomRange(70, 230);
      const color = index % 3 === 0 ? payload.colorLight : payload.particle;
      const shape: ParticleShape = index % 5 === 0 ? "star" : "circle";

      this.addParticle({
        x: payload.x,
        y: payload.y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        radius: randomRange(2.5, 7.5),
        life: randomRange(0.45, 0.85),
        color,
        shape,
      });
    }
  }

  /** Создает короткую искру при появлении новой плитки. */
  private spawnNewTile(payload: ICinderella2048EffectsPayload): void {
    for (let index = 0; index < 10; index += 1) {
      const angle = randomRange(0, Math.PI * 2);
      const speed = randomRange(25, 90);

      this.addParticle({
        x: payload.x,
        y: payload.y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        radius: randomRange(1.8, 4.4),
        life: randomRange(0.28, 0.5),
        color: payload.colorLight,
        shape: "diamond",
      });
    }
  }

  /** Создает праздничное конфетти для победной стадии. */
  private spawnRoyalBurst(payload: ICinderella2048EffectsPayload): void {
    for (let index = 0; index < 120; index += 1) {
      const angle = randomRange(-Math.PI, 0);
      const speed = randomRange(120, 360);
      const color = index % 2 === 0 ? payload.colorLight : payload.particle;
      const shape: ParticleShape = index % 3 === 0 ? "star" : "diamond";

      this.addParticle({
        x: payload.x,
        y: payload.y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 160,
        radius: randomRange(3, 9),
        life: randomRange(1.2, 2.2),
        color,
        shape,
      });
    }
  }

  /** Добавляет частицу в слой и общий список обновления. */
  private addParticle(props: IAddCinderella2048ParticleProps): void {
    const particle = new Cinderella2048Particle({
      scene: this.scene,
      textureName: particleTextureConfig.textureName,
      frameName: particleTextureConfig.frameNameByShape[props.shape],
      sourceShapeSize: particleTextureConfig.sourceShapeSize,
      ...props,
    });

    this.particles.push(particle);
    this.add(particle);
  }

  /** Удаляет все активные частицы. */
  private clearParticles(): void {
    for (const particle of this.particles) {
      particle.destroy();
    }

    this.particles = [];
  }
}
