import { clamp, randomRange } from "./utils";

interface ICinderella2048ParticleProps {
  scene: Phaser.Scene;
  textureName: string;
  frameName: string;
  sourceShapeSize: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  life: number;
  color: string;
}

/** Представляет одну image-частицу эффекта на базе runtime-текстуры. */
export class Cinderella2048Particle extends Phaser.GameObjects.Image {
  private vx: number;
  private vy: number;
  private life: number;
  private totalLife: number;
  private spin: number;
  private gravity: number;

  /** Создает частицу с физическими параметрами и стилем. */
  constructor(props: ICinderella2048ParticleProps) {
    super(props.scene, props.x, props.y, props.textureName, props.frameName);

    this.vx = props.vx;
    this.vy = props.vy;
    this.life = props.life;
    this.totalLife = props.life;
    this.rotation = randomRange(0, Math.PI * 2);
    this.spin = randomRange(-5, 5);
    this.gravity = randomRange(10, 70);

    /** Масштаб считается по видимой форме внутри frame-а, чтобы сохранить старый radius. */
    const scale = (props.radius * 2) / props.sourceShapeSize;

    this.setScale(scale);
    this.setTint(Phaser.Display.Color.HexStringToColor(props.color).color);
  }

  /** Обновляет положение, прозрачность и оставшееся время жизни. */
  updateParticle(deltaSeconds: number): boolean {
    this.vy += this.gravity * deltaSeconds;
    this.x += this.vx * deltaSeconds;
    this.y += this.vy * deltaSeconds;
    this.rotation += this.spin * deltaSeconds;
    this.life -= deltaSeconds;
    this.setAlpha(clamp(this.life / this.totalLife, 0, 1));

    return this.life > 0;
  }
}
