import {
  cinderella2048Config,
  Cinderella2048StageValue,
  clamp,
  easeOutBack,
  easeOutCubic,
  lerp,
} from "../model";
import type { Cind2048TileSpriteKey, ICind2048SpriteAsset, ICind2048SpriteConfig } from "../types";
import type { ICinderella2048CellBoundsProvider, ICinderella2048TileViewState } from "./types";
import { resolveCinderella2048StageValue } from "./resolveStage";

interface ICinderella2048TileViewProps {
  scene: Phaser.Scene;
  tile: ICinderella2048TileViewState;
  cellBoundsProvider: ICinderella2048CellBoundsProvider;
  spriteConfig: ICind2048SpriteConfig;
}

interface ICinderella2048TileUpdateProps {
  tile: ICinderella2048TileViewState;
  cellBoundsProvider: ICinderella2048CellBoundsProvider;
  time: number;
  displayValue?: number;
  mergeStartedAt?: number;
}

interface IUpdateSpriteProps {
  width: number;
  height: number;
  scale: number;
  value: number;
}

/** Отображает одну плитку 2048 как один frame атласа. */
export class Cinderella2048TileView extends Phaser.GameObjects.Image {
  readonly tileId: number;
  private tile: ICinderella2048TileViewState;
  private spriteConfig: ICind2048SpriteConfig;

  /** Создает картинку плитки из atlas-конфига. */
  constructor(props: ICinderella2048TileViewProps) {
    const { scene, tile } = props;
    const spriteAsset = props.spriteConfig[`tile${resolveCinderella2048StageValue(tile.value)}` as Cind2048TileSpriteKey];

    super(scene, 0, 0, spriteAsset.textureName, spriteAsset.frameName);

    this.tileId = tile.id;
    this.tile = tile;
    this.spriteConfig = props.spriteConfig;
    this.setOrigin(0.5);
    this.update({ tile, cellBoundsProvider: props.cellBoundsProvider, time: window.performance.now() });
  }

  /** Обновляет плитку по актуальной модели и геометрии поля. */
  update(props: ICinderella2048TileUpdateProps): void {
    this.tile = props.tile;

    const rect = this.getAnimatedBounds(props.cellBoundsProvider, props.time);
    const scale = this.getAnimatedScale(props.time, props.mergeStartedAt);
    const value = props.displayValue ?? props.tile.value;

    this.setPosition(rect.centerX, rect.centerY);
    this.updateSprite({ width: rect.width, height: rect.height, scale, value });
  }

  /** Возвращает ключ текстуры для значения плитки. */
  private getSpriteAsset(value: number): ICind2048SpriteAsset {
    const key = this.getSpriteKey(resolveCinderella2048StageValue(value));

    return this.spriteConfig[key];
  }

  /** Возвращает ключ спрайта в публичном конфиге компонента. */
  private getSpriteKey(value: Cinderella2048StageValue): Cind2048TileSpriteKey {
    return `tile${value}` as Cind2048TileSpriteKey;
  }

  /** Рассчитывает анимированные bounds плитки во время движения. */
  private getAnimatedBounds(cellBoundsProvider: ICinderella2048CellBoundsProvider, time: number): Phaser.Geom.Rectangle {
    const fromBounds = cellBoundsProvider.getCellBounds(this.tile.fromRow, this.tile.fromCol);
    const toBounds = cellBoundsProvider.getCellBounds(this.tile.row, this.tile.col);
    const rawProgress = (time - this.tile.moveStartedAt) / cinderella2048Config.timings.moveMs;
    const progress = easeOutCubic(clamp({ value: rawProgress, min: 0, max: 1 }));
    const centerX = lerp({ start: fromBounds.centerX, end: toBounds.centerX, progress });
    const centerY = lerp({ start: fromBounds.centerY, end: toBounds.centerY, progress });

    return new Phaser.Geom.Rectangle(
      centerX - toBounds.width / 2,
      centerY - toBounds.height / 2,
      toBounds.width,
      toBounds.height,
    );
  }

  /** Рассчитывает масштаб плитки для появления и слияния. */
  private getAnimatedScale(time: number, mergeStartedAt?: number): number {
    let scale = 1;

    if (this.tile.justCreated) {
      const progress = clamp({ value: (time - this.tile.createdAt) / cinderella2048Config.timings.spawnMs, min: 0, max: 1 });
      scale = 0.62 + easeOutBack(progress) * 0.38;
    }

    if (this.tile.justMerged) {
      const startedAt = mergeStartedAt ?? this.tile.mergeStartedAt;
      const progress = clamp({ value: (time - startedAt) / cinderella2048Config.timings.mergeMs, min: 0, max: 1 });
      scale = Math.max(scale, 1 + Math.sin((1 - progress) * Math.PI) * 0.13);
    }

    return scale;
  }

  /** Обновляет frame плитки и подгоняет картинку под размер клетки. */
  private updateSprite(props: IUpdateSpriteProps): void {
    const spriteAsset = this.getSpriteAsset(props.value);

    this.setTexture(spriteAsset.textureName, spriteAsset.frameName);
    this.setScale(Math.min(props.width / this.width, props.height / this.height) * props.scale);
  }
}
