import {
  Cinderella2048BackgroundManager,
  Cinderella2048EffectsLayer,
  Cinderella2048Game,
  Cinderella2048GameOverDialogManager,
  Cinderella2048Ui,
  SoundManager,
} from "./components";
import { cinderella2048SceneConfig } from "./constants";
import { getConfig } from "../../getConfig";
import { sceneKeyConfig } from "../sceneKeyConfig";

/** Phaser-сцена игрового компонента Cinderella 2048. */
export class Cinderella2048Scene extends Phaser.Scene {
  private backgroundManager?: Cinderella2048BackgroundManager;
  private gameComponent?: Cinderella2048Game;
  private ui?: Cinderella2048Ui;
  private effectsLayer?: Cinderella2048EffectsLayer;
  private gameOverDialogManager?: Cinderella2048GameOverDialogManager;
  private soundManager?: SoundManager;

  /** Создает сцену Cinderella 2048. */
  constructor() {
    super(sceneKeyConfig.game);
  }

  /** Создает игровой компонент и подписку на shutdown. */
  create(): void {
    const scene = this;
    const { backgroundConfig, boardConfig, game2048Config, soundConfig } = getConfig();

    this.backgroundManager = new Cinderella2048BackgroundManager({
      scene,
      backgroundStages: backgroundConfig.stages,
    });
    this.gameComponent = new Cinderella2048Game({
      scene,
      boardConfig,
      spriteConfig: cinderella2048SceneConfig.spriteConfig,
      game2048Config,
    });
    this.ui = new Cinderella2048Ui({
      scene,
      gameState: this.gameComponent.getState(),
    });
    this.effectsLayer = new Cinderella2048EffectsLayer(scene);
    this.gameOverDialogManager = new Cinderella2048GameOverDialogManager({
      scene,
      gameState: this.gameComponent.getState(),
      game2048Config,
    });
    this.soundManager = new SoundManager({
      scene,
      soundConfig,
    });
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.backgroundManager?.destroy();
      this.gameComponent?.destroy();
      this.ui?.destroy();
      this.effectsLayer?.destroy();
      this.gameOverDialogManager?.destroy();
      this.soundManager?.destroy();
      this.backgroundManager = undefined;
      this.gameComponent = undefined;
      this.ui = undefined;
      this.effectsLayer = undefined;
      this.gameOverDialogManager = undefined;
      this.soundManager = undefined;
    });
  }

  /** Обновляет игровой компонент сцены. */
  update(time: number, delta: number): void {
    this.gameComponent?.update(time);
    this.ui?.layout();
    this.effectsLayer?.update(delta);
  }
}
