import { getConfig } from "../../getConfig";
import { sceneKeyConfig } from "../sceneKeyConfig";
import { preloadAllAssets } from "../shared";

/** Загружает общие ассеты игры перед запуском основной сцены. */
export class BootScene extends Phaser.Scene {
  /** Создает Boot-сцену для одноразовой загрузки ассетов. */
  constructor() {
    super(sceneKeyConfig.boot);
  }

  /** Загружает публичные ассеты: плитки, фоны и atlas-спрайты. */
  preload(): void {
    const scene = this;
    const { backgroundConfig } = getConfig();

    preloadAllAssets({
      scene,
      backgroundStages: backgroundConfig.stages,
    });
  }

  /** Запускает основную игровую сцену после завершения preload. */
  create(): void {
    this.scene.start(sceneKeyConfig.game);
  }
}
