import { SceneEvents } from "../../../../common";
import type { Observable, UnSubscriber } from "../../../../common";
import { openCommonModalInScene } from "../../../../common/game-core";
import type { ICommonModalSceneHandle } from "../../../../common/game-core";
import { cinderella2048Config, formatNumber } from "../Cinderella2048Game/model";
import type { IGame2048Config } from "../Cinderella2048Game/model";
import type { ICinderella2048GameState } from "../Cinderella2048Game";
import { Cinderella2048GameOverDialogView } from "./Cinderella2048GameOverDialogView";
import type { ICinderella2048GameOverDialogCopy } from "./Cinderella2048GameOverDialogView";
import type { ICinderella2048DialogRequest, ICinderella2048GameOverDialogEvents } from "./events";

interface ICinderella2048GameOverDialogManagerProps {
  scene: Phaser.Scene;
  gameState: Observable<ICinderella2048GameState>;
  game2048Config: IGame2048Config;
}

const cinderella2048DialogManagerConfig = {
  /** Ждем полную цепочку финального хода: скольжение плиток, затем pop слияния или появление новой плитки. */
  openDelayMs: Math.max(
    cinderella2048Config.timings.moveMs + cinderella2048Config.timings.mergeMs,
    cinderella2048Config.timings.moveMs + cinderella2048Config.timings.spawnMs,
  ),
} as const;

/** Управляет стандартным диалогом победы и конца игры через modal scene. */
export class Cinderella2048GameOverDialogManager extends Phaser.GameObjects.Zone {
  private readonly sceneEvents: SceneEvents<ICinderella2048GameOverDialogEvents>;
  private readonly stateUnSub: UnSubscriber;
  private dialog?: ICommonModalSceneHandle;
  private pendingDialogTimer?: Phaser.Time.TimerEvent;
  private currentState: ICinderella2048GameState;

  /** Создает manager и подписывает его на статус игры. */
  constructor(private readonly props: ICinderella2048GameOverDialogManagerProps) {
    super(props.scene, 0, 0);

    this.sceneEvents = new SceneEvents<ICinderella2048GameOverDialogEvents>({
      scene: props.scene,
      autoUnSub: this,
    });
    this.currentState = props.gameState.getState();
    this.stateUnSub = props.gameState.on((state) => this.handleGameStateChange(state), "status");
    props.scene.add.existing(this);
    this.handleGameStateChange(this.currentState);
  }

  /** Закрывает активный диалог и снимает подписки. */
  destroy(fromScene?: boolean): void {
    this.stateUnSub();
    this.clearPendingDialog();
    this.sceneEvents.unSubscribeAll();
    this.dialog?.destroy();
    this.dialog = undefined;
    super.destroy(fromScene);
  }

  /** Реагирует на терминальный статус игры и откладывает модалку до завершения анимаций поля. */
  private handleGameStateChange(state: ICinderella2048GameState): void {
    const { scene } = this.props;

    this.currentState = state;
    this.clearPendingDialog();

    if (state.status === "playing") {
      this.dialog?.destroy();
      this.dialog = undefined;
      return;
    }

    this.pendingDialogTimer = scene.time.delayedCall(
      cinderella2048DialogManagerConfig.openDelayMs,
      () => this.openCurrentStateDialog(),
    );
  }

  /** Открывает диалог только если терминальный статус все еще актуален после задержки. */
  private openCurrentStateDialog(): void {
    const { status, canUndo, canContinueAfterWin, hasAvailableMoves, isMaxTileReached } =
      this.currentState;

    this.pendingDialogTimer = undefined;

    if (status === "playing") {
      return;
    }

    this.openDialog({ status, canUndo, canContinueAfterWin, hasAvailableMoves, isMaxTileReached });
  }

  /** Отменяет отложенное открытие диалога при смене статуса или уничтожении manager. */
  private clearPendingDialog(): void {
    this.pendingDialogTimer?.remove(false);
    this.pendingDialogTimer = undefined;
  }

  /** Открывает диалог поверх игры и блокирует parent scene стандартным overlay. */
  private openDialog(request: ICinderella2048DialogRequest): void {
    const { scene } = this.props;

    this.dialog?.destroy();
    this.dialog = openCommonModalInScene({
      parentScene: scene,
      createContent: (scene) => this.createDialogContent(scene, request),
      props: {
        animationDuration: 180,
        overlayAlpha: 0.62,
        overlayColor: "#0d0b19",
        isCloseOnOverlayClick: false,
        onClose: () => {
          this.dialog = undefined;
        },
      },
    });
  }

  /** Создает графику и кнопки диалога в отдельной modal scene. */
  private createDialogContent(
    scene: Phaser.Scene,
    request: ICinderella2048DialogRequest,
  ): Cinderella2048GameOverDialogView {
    const dialogView = new Cinderella2048GameOverDialogView({
      scene,
      copy: this.resolveCopy(request),
      onPrimaryClick: () => this.handlePrimaryClick(request),
      onSecondaryClick: () => this.handleSecondaryClick(request),
    });

    scene.add.existing(dialogView);

    return dialogView;
  }

  /** Возвращает тексты диалога по текущему состоянию игры. */
  private resolveCopy(request: ICinderella2048DialogRequest): ICinderella2048GameOverDialogCopy {
    const { game2048Config } = this.props;

    if (request.status === "win") {
      /** Финал не смешивается с обычной победой: у игрока больше нет следующей цели. */
      if (request.isMaxTileReached) {
        const noMovesText = request.hasAvailableMoves ? "" : " Ходов больше нет.";

        return {
          title: "Финальная плитка собрана",
          message: `Вы собрали финальную плитку ${formatNumber(game2048Config.maxTileValue)}.${noMovesText}`,
          primaryText: "Новая игра",
        };
      }

      if (!request.canContinueAfterWin) {
        return {
          title: "Принцесса собрана",
          message: `Вы достигли ${formatNumber(game2048Config.winValue)}. Ходов больше нет.`,
          primaryText: "Новая игра",
        };
      }

      return {
        title: "Принцесса собрана",
        message: `Вы достигли ${formatNumber(game2048Config.winValue)}. Можно продолжить и попытаться собрать финальную плитку ${formatNumber(game2048Config.maxTileValue)}.`,
        primaryText: "Продолжить",
        secondaryText: "Новая игра",
      };
    }

    return {
      title: "Ходов больше нет",
      message: "Поле заполнено, а одинаковых соседних плиток не осталось.",
      primaryText: "Новая игра",
      secondaryText: request.canUndo ? "Шаг назад" : "Новая игра",
    };
  }

  /** Выполняет основное действие диалога и закрывает modal scene. */
  private handlePrimaryClick(request: ICinderella2048DialogRequest): void {
    const dialog = this.dialog;

    if (!dialog) {
      return;
    }

    this.dialog = undefined;

    if (request.status === "win" && request.canContinueAfterWin) {
      this.sceneEvents.emit("cinderella2048ContinueRequest");
    } else {
      this.sceneEvents.emit("cinderella2048NewGameRequest");
    }

    dialog.close();
  }

  /** Выполняет вторичное действие диалога и закрывает modal scene. */
  private handleSecondaryClick(request: ICinderella2048DialogRequest): void {
    const dialog = this.dialog;

    if (!dialog) {
      return;
    }

    this.dialog = undefined;

    if (request.status === "win" || !request.canUndo) {
      this.sceneEvents.emit("cinderella2048NewGameRequest");
    } else {
      this.sceneEvents.emit("cinderella2048UndoRequest");
    }

    dialog.close();
  }
}
