/**
 * Проверяет, что число является положительной степенью двойки.
 * если переданы options = проверяет что >= min, <= max
 * */
export function isPowerOfTwo(n: number, options: { min?: number; max?: number } = {}) {
  if (options.min != null && n < options.min) return false;
  if (options.max != null && n > options.max) return false;
  // Число должно быть целым, больше нуля и проходить побитовую проверку
  return Number.isInteger(n) && n > 0 && Number.isInteger(Math.log2(n));
}
