import { IRuntimeTextureConfig } from "./types";

export interface IGenerateRuntimeTexturesProps {
    scene: Phaser.Scene;
    textures: IRuntimeTextureConfig[];
}

/**
 * Генерирует canvas-текстуры по декларативному списку, не привязываясь к конкретному эффекту.
 *
 * Runtime-текстуры регистрируются в глобальном Phaser TextureManager. Настоятельно рекомендуется
 * вызывать генерацию один раз в Boot-сцене, чтобы избежать коллизий texture key между сценами.
 */
export function generateRuntimeTextures(props: IGenerateRuntimeTexturesProps): void {
    const { scene, textures } = props;

    for (const textureConfig of textures) {
        generateRuntimeTexture({
            scene,
            textureConfig,
        });
    }
}

interface IGenerateRuntimeTextureProps {
    scene: Phaser.Scene;
    textureConfig: IRuntimeTextureConfig;
}

/** Создает одну runtime-текстуру, если она еще не зарегистрирована в Phaser texture manager. */
function generateRuntimeTexture(props: IGenerateRuntimeTextureProps): void {
    const { scene, textureConfig } = props;
    const { textureName, width, height, generatorFn } = textureConfig;

    if (scene.textures.exists(textureName)) {
        warnIfRuntimeTextureSizeMismatch({
            scene,
            textureConfig,
        });

        return;
    }

    const canvasTexture = scene.textures.createCanvas(textureName, width, height);

    if (canvasTexture == null) {
        throw new Error(`Runtime texture "${textureName}" was not created`);
    }

    const context = canvasTexture.getContext();

    context.clearRect(0, 0, width, height);
    generatorFn({
        scene,
        textureName,
        width,
        height,
        context,
    });
    canvasTexture.refresh();
}

interface IWarnIfRuntimeTextureSizeMismatchProps {
    scene: Phaser.Scene;
    textureConfig: IRuntimeTextureConfig;
}

/** Предупреждает о коллизии runtime texture key с другими размерами canvas. */
function warnIfRuntimeTextureSizeMismatch(props: IWarnIfRuntimeTextureSizeMismatchProps): void {
    const { scene, textureConfig } = props;
    const texture = scene.textures.get(textureConfig.textureName);
    const source = texture.source[0];

    if (source == null) {
        console.warn(`Runtime texture "${textureConfig.textureName}" exists without texture source`);

        return;
    }

    if (source.width === textureConfig.width && source.height === textureConfig.height) {
        return;
    }

    console.warn(
        `Runtime texture "${textureConfig.textureName}" already exists with another size: `
        + `${source.width}x${source.height}, requested ${textureConfig.width}x${textureConfig.height}`,
    );
}
