import { MoveDirection } from "../model";
import { Cinderella2048BoardView } from "./Cinderella2048BoardView";

interface ICinderella2048InputControllerProps {
  scene: Phaser.Scene;
  boardView: Cinderella2048BoardView;
  onMove: (direction: MoveDirection) => void;
  onRestart: () => void;
}

/** Преобразует клавиатуру и свайпы в направления ходов. */
export class Cinderella2048InputController {
  private pointerActive: boolean;
  private startX: number;
  private startY: number;
  private lastX: number;
  private lastY: number;
  private readonly minSwipeDistance = 36;

  /** Подписывает контроллер на ввод Phaser-сцены. */
  constructor(private props: ICinderella2048InputControllerProps) {
    this.pointerActive = false;
    this.startX = 0;
    this.startY = 0;
    this.lastX = 0;
    this.lastY = 0;

    props.scene.input.keyboard?.on("keydown", this.handleKeyDown, this);
    props.scene.input.on(Phaser.Input.Events.POINTER_DOWN, this.handlePointerDown, this);
    props.scene.input.on(Phaser.Input.Events.POINTER_MOVE, this.handlePointerMove, this);
    props.scene.input.on(Phaser.Input.Events.POINTER_UP, this.handlePointerUp, this);
    props.scene.input.on(Phaser.Input.Events.POINTER_UP_OUTSIDE, this.handlePointerCancel, this);
  }

  /** Снимает подписки на ввод сцены. */
  destroy(): void {
    this.props.scene.input.keyboard?.off("keydown", this.handleKeyDown, this);
    this.props.scene.input.off(Phaser.Input.Events.POINTER_DOWN, this.handlePointerDown, this);
    this.props.scene.input.off(Phaser.Input.Events.POINTER_MOVE, this.handlePointerMove, this);
    this.props.scene.input.off(Phaser.Input.Events.POINTER_UP, this.handlePointerUp, this);
    this.props.scene.input.off(
      Phaser.Input.Events.POINTER_UP_OUTSIDE,
      this.handlePointerCancel,
      this,
    );
  }

  /** Обрабатывает нажатия клавиш. */
  private handleKeyDown(event: KeyboardEvent): void {
    const direction = this.resolveDirectionFromKey(event.key);

    if (direction) {
      event.preventDefault();
      this.props.onMove(direction);
      return;
    }

    if (event.key === "r" || event.key === "R" || event.key === "к" || event.key === "К") {
      event.preventDefault();
      this.props.onRestart();
    }
  }

  /** Запоминает начало свайпа внутри доски. */
  private handlePointerDown(pointer: Phaser.Input.Pointer): void {
    if (!this.props.boardView.containsPoint(pointer.worldX, pointer.worldY)) {
      return;
    }

    this.pointerActive = true;
    this.startX = pointer.worldX;
    this.startY = pointer.worldY;
    this.lastX = pointer.worldX;
    this.lastY = pointer.worldY;
  }

  /** Запоминает текущую точку свайпа. */
  private handlePointerMove(pointer: Phaser.Input.Pointer): void {
    if (!this.pointerActive) {
      return;
    }

    this.lastX = pointer.worldX;
    this.lastY = pointer.worldY;
  }

  /** Завершает свайп и отправляет направление. */
  private handlePointerUp(pointer: Phaser.Input.Pointer): void {
    if (!this.pointerActive) {
      return;
    }

    this.pointerActive = false;
    this.lastX = pointer.worldX;
    this.lastY = pointer.worldY;

    const direction = this.resolveDirectionFromSwipe(
      this.lastX - this.startX,
      this.lastY - this.startY,
    );

    if (direction) {
      this.props.onMove(direction);
    }
  }

  /** Отменяет активный свайп. */
  private handlePointerCancel(): void {
    this.pointerActive = false;
  }

  /** Преобразует клавишу в направление движения. */
  private resolveDirectionFromKey(key: string): MoveDirection | null {
    if (key === "ArrowUp" || key === "w" || key === "W" || key === "ц" || key === "Ц") {
      return MoveDirection.up;
    }

    if (key === "ArrowRight" || key === "d" || key === "D" || key === "в" || key === "В") {
      return MoveDirection.right;
    }

    if (key === "ArrowDown" || key === "s" || key === "S" || key === "ы" || key === "Ы") {
      return MoveDirection.down;
    }

    if (key === "ArrowLeft" || key === "a" || key === "A" || key === "ф" || key === "Ф") {
      return MoveDirection.left;
    }

    return null;
  }

  /** Преобразует вектор свайпа в направление движения. */
  private resolveDirectionFromSwipe(dx: number, dy: number): MoveDirection | undefined {
    const absX = Math.abs(dx);
    const absY = Math.abs(dy);

    if (Math.max(absX, absY) < this.minSwipeDistance) {
      return;
    }

    if (absX > absY) {
      return dx > 0 ? MoveDirection.right : MoveDirection.left;
    }

    return dy > 0 ? MoveDirection.down : MoveDirection.up;
  }
}
